1	import { supabase } from '$lib/supabaseClient';
2	import type { ReceiptRow } from '$lib/models/Receipt';
3	import type { TransactionRow } from '$lib/models/Transaction';
4	import type {
5		ReconciliationResult,
6		ReconciliationOptions,
7		MatchedPair,
8		UnmatchedReceipt,
9		UnmatchedTransaction,
10		ReconciliationDisplayRow,
11		ReconciliationSort,
12		DuplicateReceiptInfo,
13		ManualMatchRequest
14	} from '$lib/models/Reconciliation';
15	import { withRetry } from '$lib/utils/retry';
16	
17	/**
18	 * Service for reconciling receipts with credit card/bank transactions
19	 *
20	 * Matching rules:
21	 * - Amounts must be the same (within tolerance)
22	 * - Dates must be within 3 days of each other
23	 * - Vendor names are ignored (they're inconsistent)
24	 */
25	export class ReconciliationService {
26		static #instance: ReconciliationService | null = null;
27	
28		static get(): ReconciliationService {
29			return (this.#instance ??= new ReconciliationService());
30		}
31	
32		private constructor() {}
33	
34		/**
35		 * Performs automatic matching of receipts and transactions within a date range
36		 */
37		async reconcile(familyId: string, options: ReconciliationOptions): Promise<ReconciliationResult> {
38			return withRetry(async () => {
39				const maxDaysDifference = options.maxDaysDifference ?? 3;
40				const amountTolerance = options.amountTolerance ?? 0.01;
41	
42				// Fetch receipts in date range
43				const { data: receipts, error: receiptsError } = await supabase
44					.from('receipts')
45					.select('*')
46					.eq('family_id', familyId)
47					.gte('transaction_date', options.startDate)
48					.lte('transaction_date', options.endDate)
49					.not('transaction_date', 'is', null)
50					.not('total_amount', 'is', null);
51	
52				if (receiptsError) throw receiptsError;
53	
54				// Fetch all transactions in date range (including excluded ones for visibility)
55				const { data: transactions, error: transactionsError } = await supabase
56					.from('transactions')
57					.select('*')
58					.eq('family_id', familyId)
59					.gte('transaction_date', options.startDate)
60					.lte('transaction_date', options.endDate);
61	
62				if (transactionsError) throw transactionsError;
63	
64				const allReceipts = (receipts as ReceiptRow[]) || [];
65				const allTransactions = (transactions as TransactionRow[]) || [];
66	
67				// Separate already matched receipts if we want to include them
68				const alreadyMatchedReceipts = options.includeManuallMatched
69					? allReceipts.filter((r) => r.matched_transaction_id !== null)
70					: [];
71	
72				const unmatchedReceipts = allReceipts.filter((r) => r.matched_transaction_id === null);
73	
74				// Get IDs of transactions that are already matched to receipts
75				const alreadyMatchedTransactionIds = new Set(
76					alreadyMatchedReceipts
77						.map((r) => r.matched_transaction_id)
78						.filter((id): id is string => id !== null)
79				);
80	
81				// Filter out already matched and excluded transactions from the matching pool
82				// Excluded transactions are still shown in UI but not available for matching
83				const unmatchedTransactions = allTransactions.filter(
84					(t) => !alreadyMatchedTransactionIds.has(t.id) && !t.excluded
85				);
86	
87				// Find matches using the matching algorithm
88				const foreignCurrencyTolerancePercent = options.foreignCurrencyTolerancePercent ?? 0.05;
89	
90				const matchResult = this.performMatching(
91					unmatchedReceipts,
92					unmatchedTransactions,
93					maxDaysDifference,
94					amountTolerance,
95					foreignCurrencyTolerancePercent
96				);
97	
98				// Get excluded transactions to display them separately
99				const excludedTransactions = allTransactions.filter((t) => t.excluded);
100	
101				// Add already matched receipts to the result
102				const matchedPairs: MatchedPair[] = [...matchResult.matched];
103	
104				for (const receipt of alreadyMatchedReceipts) {
105					const transaction = allTransactions.find((t) => t.id === receipt.matched_transaction_id);
106					if (transaction) {
107						matchedPairs.push({
108							receipt,
109							transaction,
110							matchConfidence: 'high' // Manual matches are high confidence
111						});
112					}
113				}
114	
115				// Add excluded transactions to unmatched list (they won't have potential matches)
116				const excludedUnmatchedTransactions: UnmatchedTransaction[] = excludedTransactions.map(
117					(transaction) => ({
118						transaction,
119						potentialMatches: [] // Excluded transactions don't get potential matches
120					})
121				);
122	
123				const allUnmatchedTransactions = [
124					...matchResult.unmatchedTransactions,
125					...excludedUnmatchedTransactions
126				];
127	
128				// Calculate stats (exclude excluded transactions from total count for stats purposes)
129				const nonExcludedTransactionCount = allTransactions.filter((t) => !t.excluded).length;
130				const stats = {
131					totalReceipts: allReceipts.length,
132					totalTransactions: nonExcludedTransactionCount,
133					matchedCount: matchedPairs.length,
134					unmatchedReceiptCount: matchResult.unmatchedReceipts.length,
135					unmatchedTransactionCount: matchResult.unmatchedTransactions.length,
136					matchRate:
137						allReceipts.length > 0 ? Math.round((matchedPairs.length / allReceipts.length) * 100) : 0
138				};
139	
140				return {
141					matched: matchedPairs,
142					unmatchedReceipts: matchResult.unmatchedReceipts,
143					unmatchedTransactions: allUnmatchedTransactions,
144					stats
145				};
146			});
147		}
148	
149		/**
150		 * Core matching algorithm
151		 * Returns matched pairs and unmatched items
152		 */
153		private performMatching(
154			receipts: ReceiptRow[],
155			transactions: TransactionRow[],
156			maxDaysDifference: number,
157			amountTolerance: number,
158			foreignCurrencyTolerancePercent: number = 0.05
159		): {
160			matched: MatchedPair[];
161			unmatchedReceipts: UnmatchedReceipt[];
162			unmatchedTransactions: UnmatchedTransaction[];
163		} {
164			const matched: MatchedPair[] = [];
165			const usedTransactionIds = new Set<string>();
166			const usedReceiptIds = new Set<string>();
167	
168			// First pass: Find exact or high-confidence matches
169			for (const receipt of receipts) {
170				if (!receipt.total_amount || !receipt.transaction_date) continue;
171	
172				const potentialMatches = this.findPotentialMatches(
173					receipt,
174					transactions,
175					maxDaysDifference,
176					amountTolerance,
177					foreignCurrencyTolerancePercent
178				);
179	
180				// Filter out already used transactions
181				const availableMatches = potentialMatches.filter(
182					(pm) => !usedTransactionIds.has(pm.transaction.id)
183				);
184	
185				if (availableMatches.length > 0) {
186					// Take the best match (first one, as they're sorted by confidence)
187					const bestMatch = availableMatches[0];
188					matched.push({
189						receipt,
190						transaction: bestMatch.transaction,
191						matchConfidence: bestMatch.confidence
192					});
193					usedTransactionIds.add(bestMatch.transaction.id);
194					usedReceiptIds.add(receipt.id);
195				}
196			}
197	
198			// Build unmatched receipts list
199			const unmatchedReceipts: UnmatchedReceipt[] = receipts
200				.filter((r) => !usedReceiptIds.has(r.id))
201				.map((receipt) => {
202					const potentialMatches = this.findPotentialMatches(
203						receipt,
204						transactions,
205						maxDaysDifference,
206						amountTolerance,
207						foreignCurrencyTolerancePercent
208					)
209						.filter((pm) => !usedTransactionIds.has(pm.transaction.id))
210						.map((pm) => pm.transaction);
211	
212					return {
213						receipt,
214						potentialMatches
215					};
216				});
217	
218			// Build unmatched transactions list
219			const unmatchedTransactions: UnmatchedTransaction[] = transactions
220				.filter((t) => !usedTransactionIds.has(t.id))
221				.map((transaction) => {
222					const potentialMatches = this.findPotentialMatchesForTransaction(
223						transaction,
224						receipts,
225						maxDaysDifference,
226						amountTolerance,
227						foreignCurrencyTolerancePercent
228					)
229						.filter((pm) => !usedReceiptIds.has(pm.receipt.id))
230						.map((pm) => pm.receipt);
231	
232					return {
233						transaction,
234						potentialMatches
235					};
236				});
237	
238			return {
239				matched,
240				unmatchedReceipts,
241				unmatchedTransactions
242			};
243		}
244	
245		/**
246		 * Finds potential transaction matches for a given receipt
247		 */
248		private findPotentialMatches(
249			receipt: ReceiptRow,
250			transactions: TransactionRow[],
251			maxDaysDifference: number,
252			amountTolerance: number,
253			foreignCurrencyTolerancePercent: number = 0.05
254		): Array<{ transaction: TransactionRow; confidence: 'high' | 'medium' | 'low' }> {
255			if (!receipt.total_amount || !receipt.transaction_date) return [];
256	
257			const receiptDate = new Date(receipt.transaction_date);
258			const rawReceiptAmount = Math.abs(receipt.total_amount);
259	
260			// #{#fcr3a} Determine if this is a foreign currency receipt
261			const isForeignCurrency =
262				receipt.currency !== null && receipt.currency !== 'CAD';
263	
264			// For foreign currency: convert to CAD using rate stored on receipt
265			let receiptAmountCAD: number;
266			let useForeignCurrencyTolerance = false;
267	
268			if (isForeignCurrency) {
269				if (!receipt.exchange_rate_to_cad) {
270					// No exchange rate stored — cannot match this receipt
271					return [];
272				}
273				receiptAmountCAD = rawReceiptAmount * receipt.exchange_rate_to_cad;
274				useForeignCurrencyTolerance = true;
275			} else {
276				receiptAmountCAD = rawReceiptAmount;
277			}
278	
279			const matches: Array<{
280				transaction: TransactionRow;
281				confidence: 'high' | 'medium' | 'low';
282				score: number;
283			}> = [];
284	
285			for (const transaction of transactions) {
286				const transactionDate = new Date(transaction.transaction_date);
287				const transactionAmount = Math.abs(transaction.amount);
288	
289				// #{#fcr3a} Check amount match — use percentage tolerance for foreign currency
290				const amountDiff = Math.abs(receiptAmountCAD - transactionAmount);
291	
292				if (useForeignCurrencyTolerance) {
293					// Percentage-based tolerance for foreign currency
294					const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;
295					if (percentDiff > foreignCurrencyTolerancePercent) continue;
296				} else {
297					// Fixed tolerance for CAD
298					if (amountDiff > amountTolerance) continue;
299				}
300	
301				// Check date difference (within max days)
302				const daysDiff = Math.abs(
303					(receiptDate.getTime() - transactionDate.getTime()) / (1000 * 60 * 60 * 24)
304				);
305				if (daysDiff > maxDaysDifference) continue;
306	
307				// Calculate match confidence
308				let score = 0;
309				let confidence: 'high' | 'medium' | 'low' = 'low';
310	
311				if (useForeignCurrencyTolerance) {
312					// #{#fcr3a} Foreign currency confidence based on percentage difference
313					const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;
314					if (percentDiff <= 0.02) {
315						score += 10;
316					} else if (percentDiff <= 0.03) {
317						score += 6;
318					} else {
319						score += 3;
320					}
321	
322					// Date-based scoring
323					if (daysDiff === 0) {
324						score += 10;
325						if (percentDiff <= 0.02) confidence = 'high';
326						else if (percentDiff <= 0.03) confidence = 'medium';
327						else confidence = 'low';
328					} else if (daysDiff <= 1) {
329						score += 5;
330						if (percentDiff <= 0.02) confidence = 'medium';
331						else confidence = 'low';
332					} else {
333						score += 2;
334						confidence = 'low';
335					}
336				} else {
337					// Original CAD confidence scoring (unchanged)
338					if (amountDiff < 0.01) {
339						score += 10;
340					}
341	
342					if (daysDiff === 0) {
343						score += 10;
344						confidence = 'high';
345					} else if (daysDiff <= 1) {
346						score += 5;
347						confidence = 'medium';
348					} else {
349						score += 2;
350						confidence = 'low';
351					}
352				}
353	
354				matches.push({ transaction, confidence, score });
355			}
356	
357			// Sort by score (best matches first)
358			matches.sort((a, b) => b.score - a.score);
359	
360			return matches.map((m) => ({ transaction: m.transaction, confidence: m.confidence }));
361		}
