363		/**
364		 * Finds potential receipt matches for a given transaction
365		 */
366		private findPotentialMatchesForTransaction(
367			transaction: TransactionRow,
368			receipts: ReceiptRow[],
369			maxDaysDifference: number,
370			amountTolerance: number,
371			foreignCurrencyTolerancePercent: number = 0.05
372		): Array<{ receipt: ReceiptRow; confidence: 'high' | 'medium' | 'low' }> {
373			const transactionDate = new Date(transaction.transaction_date);
374			const transactionAmount = Math.abs(transaction.amount);
375	
376			const matches: Array<{
377				receipt: ReceiptRow;
378				confidence: 'high' | 'medium' | 'low';
379				score: number;
380			}> = [];
381	
382			for (const receipt of receipts) {
383				if (!receipt.total_amount || !receipt.transaction_date) continue;
384	
385				const receiptDate = new Date(receipt.transaction_date);
386				const rawReceiptAmount = Math.abs(receipt.total_amount);
387	
388				// #{#fcr3a} Handle foreign currency receipts
389				const isForeignCurrency =
390					receipt.currency !== null && receipt.currency !== 'CAD';
391	
392				let receiptAmountCAD: number;
393				let useForeignCurrencyTolerance = false;
394	
395				if (isForeignCurrency) {
396					if (!receipt.exchange_rate_to_cad) continue; // No rate stored — skip
397					receiptAmountCAD = rawReceiptAmount * receipt.exchange_rate_to_cad;
398					useForeignCurrencyTolerance = true;
399				} else {
400					receiptAmountCAD = rawReceiptAmount;
401				}
402	
403				// Check amount match
404				const amountDiff = Math.abs(receiptAmountCAD - transactionAmount);
405	
406				if (useForeignCurrencyTolerance) {
407					const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;
408					if (percentDiff > foreignCurrencyTolerancePercent) continue;
409				} else {
410					if (amountDiff > amountTolerance) continue;
411				}
412	
413				// Check date difference
414				const daysDiff = Math.abs(
415					(receiptDate.getTime() - transactionDate.getTime()) / (1000 * 60 * 60 * 24)
416				);
417				if (daysDiff > maxDaysDifference) continue;
418	
419				// Calculate match confidence
420				let score = 0;
421				let confidence: 'high' | 'medium' | 'low' = 'low';
422	
423				if (useForeignCurrencyTolerance) {
424					const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;
425					if (percentDiff <= 0.02) score += 10;
426					else if (percentDiff <= 0.03) score += 6;
427					else score += 3;
428	
429					if (daysDiff === 0) {
430						score += 10;
431						if (percentDiff <= 0.02) confidence = 'high';
432						else if (percentDiff <= 0.03) confidence = 'medium';
433						else confidence = 'low';
434					} else if (daysDiff <= 1) {
435						score += 5;
436						if (percentDiff <= 0.02) confidence = 'medium';
437						else confidence = 'low';
438					} else {
439						score += 2;
440						confidence = 'low';
441					}
442				} else {
443					if (amountDiff < 0.01) score += 10;
444					if (daysDiff === 0) {
445						score += 10;
446						confidence = 'high';
447					} else if (daysDiff <= 1) {
448						score += 5;
449						confidence = 'medium';
450					} else {
451						score += 2;
452						confidence = 'low';
453					}
454				}
455	
456				matches.push({ receipt, confidence, score });
457			}
458	
459			matches.sort((a, b) => b.score - a.score);
460			return matches.map((m) => ({ receipt: m.receipt, confidence: m.confidence }));
461		}
