463		/**
464		 * Manually match a receipt to a transaction
465		 */
466		async manualMatch(request: ManualMatchRequest): Promise<ReceiptRow> {
467			return withRetry(async () => {
468				const { data, error } = await supabase
469					.from('receipts')
470					.update({ matched_transaction_id: request.transactionId })
471					.eq('id', request.receiptId)
472					.select('*')
473					.single();
474	
475				if (error) throw error;
476				return data as ReceiptRow;
477			});
478		}
479	
480		/**
481		 * Manually unmatch a receipt from its transaction
482		 */
483		async manualUnmatch(receiptId: string): Promise<ReceiptRow> {
484			return withRetry(async () => {
485				const { data, error } = await supabase
486					.from('receipts')
487					.update({ matched_transaction_id: null })
488					.eq('id', receiptId)
489					.select('*')
490					.single();
491	
492				if (error) throw error;
493				return data as ReceiptRow;
494			});
495		}
