497		/**
498		 * Converts reconciliation result to display rows for the UI table
499		 */
500		convertToDisplayRows(
501			result: ReconciliationResult,
502			sort?: ReconciliationSort
503		): ReconciliationDisplayRow[] {
504			const rows: ReconciliationDisplayRow[] = [];
505	
506			// #{#fcr5b} Helper to compute converted CAD amount from receipt's stored rate
507			const getConvertedCAD = (receipt: ReceiptRow | null): number | null => {
508				if (!receipt || !receipt.total_amount) return null;
509				if (!receipt.currency || receipt.currency === 'CAD') return null;
510				if (!receipt.exchange_rate_to_cad) return null;
511				return receipt.total_amount * receipt.exchange_rate_to_cad;
512			};
513	
514			// Add matched pairs (green rows at top)
515			for (const pair of result.matched) {
516				rows.push({
517					id: `matched-${pair.receipt.id}-${pair.transaction.id}`,
518					type: 'matched',
519					receipt: pair.receipt,
520					transaction: pair.transaction,
521					date: pair.receipt.transaction_date,
522					vendor: pair.receipt.merchant_name || pair.transaction.vendor_name,
523					amount: pair.receipt.total_amount,
524					creditCard: pair.transaction.credit_card_type,
525					matchConfidence: pair.matchConfidence,
526					convertedAmountCAD: getConvertedCAD(pair.receipt)
527				});
528			}
529	
530			// Add unmatched receipts
531			for (const unmatched of result.unmatchedReceipts) {
532				rows.push({
533					id: `receipt-${unmatched.receipt.id}`,
534					type: 'unmatchedReceipt',
535					receipt: unmatched.receipt,
536					transaction: null,
537					date: unmatched.receipt.transaction_date,
538					vendor: unmatched.receipt.merchant_name,
539					amount: unmatched.receipt.total_amount,
540					creditCard: unmatched.receipt.credit_card_name,
541					convertedAmountCAD: getConvertedCAD(unmatched.receipt)
542				});
543			}
544	
545			// Add unmatched transactions
546			for (const unmatched of result.unmatchedTransactions) {
547				rows.push({
548					id: `transaction-${unmatched.transaction.id}`,
549					type: 'unmatchedTransaction',
550					receipt: null,
551					transaction: unmatched.transaction,
552					date: unmatched.transaction.transaction_date,
553					vendor: unmatched.transaction.vendor_name,
554					amount: unmatched.transaction.amount,
555					creditCard: unmatched.transaction.credit_card_type,
556					convertedAmountCAD: null
557				});
558			}
559	
560			// Apply sorting if specified
561			if (sort) {
562				return this.sortDisplayRows(rows, sort);
563			}
564	
565			return rows;
566		}
567	
568		/**
569		 * Sorts display rows by the specified field and direction
570		 */
571		private sortDisplayRows(
572			rows: ReconciliationDisplayRow[],
573			sort: ReconciliationSort
574		): ReconciliationDisplayRow[] {
575			const sortedRows = [...rows];
576			const direction = sort.direction === 'asc' ? 1 : -1;
577	
578			sortedRows.sort((a, b) => {
579				let aVal: string | number;
580				let bVal: string | number;
581	
582				switch (sort.field) {
583					case 'date':
584						aVal = a.date || '';
585						bVal = b.date || '';
586						break;
587					case 'vendor':
588						aVal = a.vendor || '';
589						bVal = b.vendor || '';
590						break;
591					case 'amount':
592						aVal = a.amount || 0;
593						bVal = b.amount || 0;
594						break;
595					case 'creditCard':
596						aVal = a.creditCard || '';
597						bVal = b.creditCard || '';
598						break;
599					case 'matchStatus': {
600						const statusOrder = { matched: 0, unmatchedReceipt: 1, unmatchedTransaction: 2 };
601						aVal = statusOrder[a.type];
602						bVal = statusOrder[b.type];
603						break;
604					}
605					default:
606						return 0;
607				}
608	
609				if (typeof aVal === 'string') {
610					return direction * aVal.localeCompare(bVal as string);
611				} else {
612					return direction * (aVal - (bVal as number));
613				}
614			});
615	
616			return sortedRows;
617		}
618	}
