1	// Reconciliation models for matching receipts with transactions
2	
3	import type { ReceiptRow } from './Receipt';
4	import type { TransactionRow } from './Transaction';
5	
6	/**
7	 * Represents a matched pair of receipt and transaction
8	 */
9	export type MatchedPair = {
10		receipt: ReceiptRow;
11		transaction: TransactionRow;
12		matchConfidence: 'high' | 'medium' | 'low';
13	};
14	
15	/**
16	 * Represents an unmatched receipt (no corresponding transaction found)
17	 */
18	export type UnmatchedReceipt = {
19		receipt: ReceiptRow;
20		potentialMatches: TransactionRow[];
21	};
22	
23	/**
24	 * Represents an unmatched transaction (no corresponding receipt found)
25	 */
26	export type UnmatchedTransaction = {
27		transaction: TransactionRow;
28		potentialMatches: ReceiptRow[];
29	};
30	
31	/**
32	 * Result of the reconciliation matching process
33	 */
34	export type ReconciliationResult = {
35		matched: MatchedPair[];
36		unmatchedReceipts: UnmatchedReceipt[];
37		unmatchedTransactions: UnmatchedTransaction[];
38		stats: ReconciliationStats;
39	};
40	
41	/**
42	 * Statistics about the reconciliation
43	 */
44	export type ReconciliationStats = {
45		totalReceipts: number;
46		totalTransactions: number;
47		matchedCount: number;
48		unmatchedReceiptCount: number;
49		unmatchedTransactionCount: number;
50		matchRate: number; // Percentage of matched items
51	};
52	
53	/**
54	 * Options for reconciliation matching
55	 */
56	export type ReconciliationOptions = {
57		startDate: string; // ISO date string (YYYY-MM-DD)
58		endDate: string; // ISO date string (YYYY-MM-DD)
59		maxDaysDifference?: number; // Default: 3
60		amountTolerance?: number; // Default: 0.01 (1 cent)
61		includeManuallMatched?: boolean; // Default: true
62		foreignCurrencyTolerancePercent?: number; // #{#fcr3a} Default: 0.05 (5%)
63	};
64	
65	/**
66	 * Sorting options for reconciliation display
67	 */
68	export type ReconciliationSortField = 'date' | 'vendor' | 'amount' | 'creditCard' | 'matchStatus';
69	
70	export type ReconciliationSortDirection = 'asc' | 'desc';
71	
72	export type ReconciliationSort = {
73		field: ReconciliationSortField;
74		direction: ReconciliationSortDirection;
75	};
