import { PUBLIC_SUPABASE_ANON_KEY, PUBLIC_SUPABASE_URL } from '$env/static/public';

export class SupabaseClientSingleton {
	static #instance: SupabaseClient | null = null;

	static get(): SupabaseClient {
		if (!this.#instance) {
			if (!PUBLIC_SUPABASE_URL || !PUBLIC_SUPABASE_ANON_KEY) {
				throw new Error(
					'Supabase environment variables are not set. Define PUBLIC_SUPABASE_URL and PUBLIC_SUPABASE_ANON_KEY'
