export type MatchConfidence = 'high' | 'medium' | 'low';

/**
 * Tolerances used by the matching algorithm when comparing receipts to transactions
 */
export type MatchingTolerances = {
	maxDaysDifference: number; // Max days between receipt and transaction dates
	amountTolerance: number; // Max absolute CAD difference for same-currency matches
	foreignCurrencyTolerancePercent: number; // #{#fcr3a} Max relative difference for converted amounts
};

/**
 * Single source of truth for the matching tolerance defaults
 */
export const DEFAULT_MATCHING_TOLERANCES: MatchingTolerances = {
	maxDaysDifference: 3,
	amountTolerance: 0.01, // 1 cent
	foreignCurrencyTolerancePercent: 0.05 // 5%
};

/**
 * Fills any missing tolerance overrides with the defaults
 */
export function resolveMatchingTolerances(
	overrides: Partial<MatchingTolerances>
): MatchingTolerances {
	return {
		maxDaysDifference: overrides.maxDaysDifference ?? DEFAULT_MATCHING_TOLERANCES.maxDaysDifference,
		amountTolerance: overrides.amountTolerance ?? DEFAULT_MATCHING_TOLERANCES.amountTolerance,
		foreignCurrencyTolerancePercent:
			overrides.foreignCurrencyTolerancePercent ??
			DEFAULT_MATCHING_TOLERANCES.foreignCurrencyTolerancePercent
	};
}

