import { supabase } from '$lib/supabaseClient';
import type { ReceiptRow } from '$lib/models/Receipt';
import type { TransactionRow } from '$lib/models/Transaction';
import { resolveMatchingTolerances } from '$lib/models/Reconciliation';
import type {
	ReconciliationResult,
	ReconciliationOptions,
	ReconciliationStats,
	MatchedPair,
	MatchConfidence,
	MatchingTolerances,
	UnmatchedReceipt,
	UnmatchedTransaction,
	ReconciliationDisplayRow,
	ReconciliationSort,
	ManualMatchRequest
} from '$lib/models/Reconciliation';
import { withRetry } from '$lib/utils/retry';

const MS_PER_DAY = 1000 * 60 * 60 * 24;

// CAD scoring: an amount difference below this counts as "exact to the cent"
const EXACT_AMOUNT_DIFF = 0.01;

// #{#fcr3a} Foreign currency confidence bands (relative difference of converted amount)
const FC_HIGH_CONFIDENCE_PERCENT = 0.02;
const FC_MEDIUM_CONFIDENCE_PERCENT = 0.03;

// Score weights (higher score = better candidate)
const SCORE_AMOUNT_EXACT = 10;
const SCORE_AMOUNT_CLOSE = 6;
const SCORE_AMOUNT_NEAR = 3;
const SCORE_SAME_DAY = 10;
const SCORE_ONE_DAY_APART = 5;
const SCORE_WITHIN_RANGE = 2;

type ScoredCandidate = {
	confidence: MatchConfidence;
	score: number;
};

type MatchingOutcome = {
	matched: MatchedPair[];
	unmatchedReceipts: UnmatchedReceipt[];
	unmatchedTransactions: UnmatchedTransaction[];
};

/**
 * Service for reconciling receipts with credit card/bank transactions
 *
 * Matching rules:
 * - Amounts must be the same (within tolerance)
 * - Dates must be within 3 days of each other
 * - Vendor names are ignored (they're inconsistent)
 */
export class ReconciliationService {
	static #instance: ReconciliationService | null = null;

	static get(): ReconciliationService {
		return (this.#instance ??= new ReconciliationService());
	}

	private constructor() {}

	/**
	 * Performs automatic matching of receipts and transactions within a date range
	 */
	async reconcile(familyId: string, options: ReconciliationOptions): Promise<ReconciliationResult> {
		return withRetry(async () => {
			const tolerances = resolveMatchingTolerances(options);

			const allReceipts = await this.fetchReceiptsInRange(familyId, options);
			const allTransactions = await this.fetchTransactionsInRange(familyId, options);

			const { alreadyMatchedReceipts, unmatchedReceipts, matchableTransactions } =
				this.partitionForMatching(allReceipts, allTransactions, options.includeManuallMatched);

			const matchResult = this.performMatching(unmatchedReceipts, matchableTransactions, tolerances);

			const matchedPairs: MatchedPair[] = [
				...matchResult.matched,
				...this.buildManualMatchPairs(alreadyMatchedReceipts, allTransactions)
			];

			// Excluded transactions are still shown in the UI, just never matched
			const allUnmatchedTransactions: UnmatchedTransaction[] = [
				...matchResult.unmatchedTransactions,
				...this.buildExcludedUnmatchedTransactions(allTransactions)
			];

			return {
				matched: matchedPairs,
				unmatchedReceipts: matchResult.unmatchedReceipts,
				unmatchedTransactions: allUnmatchedTransactions,
				stats: this.computeStats(allReceipts, allTransactions, matchedPairs, matchResult)
			};
		});
	}

	private async fetchReceiptsInRange(
		familyId: string,
		options: ReconciliationOptions
	): Promise<ReceiptRow[]> {
		const { data, error } = await supabase
			.from('receipts')
			.select('*')
			.eq('family_id', familyId)
			.gte('transaction_date', options.startDate)
			.lte('transaction_date', options.endDate)
			.not('transaction_date', 'is', null)
			.not('total_amount', 'is', null);

		if (error) throw error;
		return (data as ReceiptRow[]) || [];
	}

	private async fetchTransactionsInRange(
		familyId: string,
		options: ReconciliationOptions
	): Promise<TransactionRow[]> {
		// Includes excluded transactions so they stay visible in the UI
		const { data, error } = await supabase
			.from('transactions')
			.select('*')
			.eq('family_id', familyId)
			.gte('transaction_date', options.startDate)
			.lte('transaction_date', options.endDate);

		if (error) throw error;
		return (data as TransactionRow[]) || [];
	}

	/**
	 * Splits the fetched rows into manual matches (kept as-is) and the pools
	 * available to the automatic matching algorithm
	 */
	private partitionForMatching(
		allReceipts: ReceiptRow[],
		allTransactions: TransactionRow[],
		includeManuallyMatched: boolean | undefined
	): {
		alreadyMatchedReceipts: ReceiptRow[];
		unmatchedReceipts: ReceiptRow[];
		matchableTransactions: TransactionRow[];
	} {
		const alreadyMatchedReceipts = includeManuallyMatched
			? allReceipts.filter((r) => r.matched_transaction_id !== null)
			: [];

		const unmatchedReceipts = allReceipts.filter((r) => r.matched_transaction_id === null);

		const alreadyMatchedTransactionIds = new Set(
			alreadyMatchedReceipts
				.map((r) => r.matched_transaction_id)
				.filter((id): id is string => id !== null)
		);

		// Excluded transactions are still shown in UI but not available for matching
		const matchableTransactions = allTransactions.filter(
			(t) => !alreadyMatchedTransactionIds.has(t.id) && !t.excluded
		);

		return { alreadyMatchedReceipts, unmatchedReceipts, matchableTransactions };
	}

	private buildManualMatchPairs(
		alreadyMatchedReceipts: ReceiptRow[],
		allTransactions: TransactionRow[]
	): MatchedPair[] {
		const pairs: MatchedPair[] = [];

		for (const receipt of alreadyMatchedReceipts) {
			const transaction = allTransactions.find((t) => t.id === receipt.matched_transaction_id);
			if (!transaction) continue;

			pairs.push({
				receipt,
				transaction,
				matchConfidence: 'high' // Manual matches are high confidence
			});
		}

		return pairs;
	}

	private buildExcludedUnmatchedTransactions(
		allTransactions: TransactionRow[]
	): UnmatchedTransaction[] {
		return allTransactions
			.filter((t) => t.excluded)
			.map((transaction) => ({
				transaction,
				potentialMatches: [] // Excluded transactions don't get potential matches
			}));
	}

	private computeStats(
		allReceipts: ReceiptRow[],
		allTransactions: TransactionRow[],
		matchedPairs: MatchedPair[],
		matchResult: MatchingOutcome
	): ReconciliationStats {
		// Excluded transactions don't count toward totals
		const nonExcludedTransactionCount = allTransactions.filter((t) => !t.excluded).length;

		return {
			totalReceipts: allReceipts.length,
			totalTransactions: nonExcludedTransactionCount,
			matchedCount: matchedPairs.length,
			unmatchedReceiptCount: matchResult.unmatchedReceipts.length,
			unmatchedTransactionCount: matchResult.unmatchedTransactions.length,
			matchRate:
				allReceipts.length > 0
					? Math.round((matchedPairs.length / allReceipts.length) * 100)
					: 0
		};
	}

	/**
	 * Core matching algorithm
	 * Returns matched pairs and unmatched items
	 */
	private performMatching(
		receipts: ReceiptRow[],
		transactions: TransactionRow[],
		tolerances: MatchingTolerances
	): MatchingOutcome {
		const matched = this.matchBestAvailablePairs(receipts, transactions, tolerances);

		const usedReceiptIds = new Set(matched.map((pair) => pair.receipt.id));
		const usedTransactionIds = new Set(matched.map((pair) => pair.transaction.id));

		return {
			matched,
			unmatchedReceipts: this.buildUnmatchedReceipts(
				receipts,
				transactions,
				usedReceiptIds,
				usedTransactionIds,
				tolerances
			),
			unmatchedTransactions: this.buildUnmatchedTransactions(
				receipts,
				transactions,
				usedReceiptIds,
				usedTransactionIds,
				tolerances
			)
		};
	}

	/**
	 * Greedily pairs each receipt (in order) with its best still-available transaction
	 */
	private matchBestAvailablePairs(
		receipts: ReceiptRow[],
		transactions: TransactionRow[],
		tolerances: MatchingTolerances
	): MatchedPair[] {
		const matched: MatchedPair[] = [];
		const usedTransactionIds = new Set<string>();

		for (const receipt of receipts) {
			const availableMatches = this.findPotentialMatches(receipt, transactions, tolerances).filter(
				(pm) => !usedTransactionIds.has(pm.transaction.id)
			);

			if (availableMatches.length === 0) continue;

			// Take the best match (first one, as they're sorted by confidence)
			const bestMatch = availableMatches[0];
			matched.push({
				receipt,
				transaction: bestMatch.transaction,
				matchConfidence: bestMatch.confidence
			});
			usedTransactionIds.add(bestMatch.transaction.id);
		}

		return matched;
	}

	private buildUnmatchedReceipts(
		receipts: ReceiptRow[],
		transactions: TransactionRow[],
		usedReceiptIds: Set<string>,
		usedTransactionIds: Set<string>,
		tolerances: MatchingTolerances
	): UnmatchedReceipt[] {
		return receipts
			.filter((r) => !usedReceiptIds.has(r.id))
			.map((receipt) => ({
				receipt,
				potentialMatches: this.findPotentialMatches(receipt, transactions, tolerances)
					.filter((pm) => !usedTransactionIds.has(pm.transaction.id))
					.map((pm) => pm.transaction)
			}));
	}

	private buildUnmatchedTransactions(
		receipts: ReceiptRow[],
		transactions: TransactionRow[],
		usedReceiptIds: Set<string>,
		usedTransactionIds: Set<string>,
		tolerances: MatchingTolerances
	): UnmatchedTransaction[] {
		return transactions
			.filter((t) => !usedTransactionIds.has(t.id))
			.map((transaction) => ({
				transaction,
				potentialMatches: this.findPotentialMatchesForTransaction(
					transaction,
					receipts,
					tolerances
				)
					.filter((pm) => !usedReceiptIds.has(pm.receipt.id))
					.map((pm) => pm.receipt)
			}));
	}

	/**
	 * Finds potential transaction matches for a given receipt, best first
	 */
	private findPotentialMatches(
		receipt: ReceiptRow,
		transactions: TransactionRow[],
		tolerances: MatchingTolerances
	): Array<{ transaction: TransactionRow; confidence: MatchConfidence }> {
		const scored: Array<{ transaction: TransactionRow } & ScoredCandidate> = [];

		for (const transaction of transactions) {
			const candidate = this.scoreCandidate(receipt, transaction, tolerances);
			if (candidate) scored.push({ transaction, ...candidate });
		}

		scored.sort((a, b) => b.score - a.score);
		return scored.map(({ transaction, confidence }) => ({ transaction, confidence }));
	}

	/**
	 * Finds potential receipt matches for a given transaction, best first
	 */
	private findPotentialMatchesForTransaction(
		transaction: TransactionRow,
		receipts: ReceiptRow[],
		tolerances: MatchingTolerances
	): Array<{ receipt: ReceiptRow; confidence: MatchConfidence }> {
		const scored: Array<{ receipt: ReceiptRow } & ScoredCandidate> = [];

		for (const receipt of receipts) {
			const candidate = this.scoreCandidate(receipt, transaction, tolerances);
			if (candidate) scored.push({ receipt, ...candidate });
		}

		scored.sort((a, b) => b.score - a.score);
		return scored.map(({ receipt, confidence }) => ({ receipt, confidence }));
	}

	/**
	 * Shared matching predicate: scores a receipt/transaction pair, or returns
	 * null when the pair is outside the amount/date tolerances (no match)
	 */
	private scoreCandidate(
		receipt: ReceiptRow,
		transaction: TransactionRow,
		tolerances: MatchingTolerances
	): ScoredCandidate | null {
		if (!receipt.total_amount || !receipt.transaction_date) return null;

		// #{#fcr3a} Foreign currency receipts are converted to CAD using the rate
		// stored on the receipt, and compared with a percentage tolerance
		const isForeignCurrency = receipt.currency !== null && receipt.currency !== 'CAD';
		if (isForeignCurrency && !receipt.exchange_rate_to_cad) {
			return null; // No exchange rate stored — cannot match this receipt
		}

		const rawReceiptAmount = Math.abs(receipt.total_amount);
		const receiptAmountCAD =
			isForeignCurrency && receipt.exchange_rate_to_cad
				? rawReceiptAmount * receipt.exchange_rate_to_cad
				: rawReceiptAmount;

		const transactionAmount = Math.abs(transaction.amount);
		const amountDiff = Math.abs(receiptAmountCAD - transactionAmount);
		const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;

		const withinAmountTolerance = isForeignCurrency
			? percentDiff <= tolerances.foreignCurrencyTolerancePercent
			: amountDiff <= tolerances.amountTolerance;
		if (!withinAmountTolerance) return null;

		const daysDiff = Math.abs(
			(new Date(receipt.transaction_date).getTime() -
				new Date(transaction.transaction_date).getTime()) /
				MS_PER_DAY
		);
		if (daysDiff > tolerances.maxDaysDifference) return null;

		return isForeignCurrency
			? this.scoreForeignCurrencyCandidate(percentDiff, daysDiff)
			: this.scoreCadCandidate(amountDiff, daysDiff);
	}

	/**
	 * #{#fcr3a} Foreign currency confidence based on percentage difference
	 */
	private scoreForeignCurrencyCandidate(percentDiff: number, daysDiff: number): ScoredCandidate {
		let score: number;
		if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) score = SCORE_AMOUNT_EXACT;
		else if (percentDiff <= FC_MEDIUM_CONFIDENCE_PERCENT) score = SCORE_AMOUNT_CLOSE;
		else score = SCORE_AMOUNT_NEAR;

		let confidence: MatchConfidence = 'low';
		if (daysDiff === 0) {
			score += SCORE_SAME_DAY;
			if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) confidence = 'high';
			else if (percentDiff <= FC_MEDIUM_CONFIDENCE_PERCENT) confidence = 'medium';
		} else if (daysDiff <= 1) {
			score += SCORE_ONE_DAY_APART;
			if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) confidence = 'medium';
		} else {
			score += SCORE_WITHIN_RANGE;
		}

		return { score, confidence };
	}

	/**
	 * CAD confidence based on date proximity, with a bonus for exact amounts
	 */
	private scoreCadCandidate(amountDiff: number, daysDiff: number): ScoredCandidate {
		let score = amountDiff < EXACT_AMOUNT_DIFF ? SCORE_AMOUNT_EXACT : 0;

		let confidence: MatchConfidence;
		if (daysDiff === 0) {
			score += SCORE_SAME_DAY;
			confidence = 'high';
		} else if (daysDiff <= 1) {
			score += SCORE_ONE_DAY_APART;
			confidence = 'medium';
		} else {
			score += SCORE_WITHIN_RANGE;
			confidence = 'low';
		}

		return { score, confidence };
	}

	/**
	 * Manually match a receipt to a transaction
	 */
	async manualMatch(request: ManualMatchRequest): Promise<ReceiptRow> {
		return withRetry(async () => {
			const { data, error } = await supabase
				.from('receipts')
				.update({ matched_transaction_id: request.transactionId })
				.eq('id', request.receiptId)
				.select('*')
				.single();

			if (error) throw error;
			return data as ReceiptRow;
		});
	}

	/**
	 * Manually unmatch a receipt from its transaction
	 */
	async manualUnmatch(receiptId: string): Promise<ReceiptRow> {
		return withRetry(async () => {
			const { data, error } = await supabase
				.from('receipts')
				.update({ matched_transaction_id: null })
				.eq('id', receiptId)
				.select('*')
				.single();

			if (error) throw error;
			return data as ReceiptRow;
		});
	}

	/**
	 * Converts reconciliation result to display rows for the UI table
	 */
	convertToDisplayRows(
		result: ReconciliationResult,
		sort?: ReconciliationSort
	): ReconciliationDisplayRow[] {
		const rows: ReconciliationDisplayRow[] = [];

		// #{#fcr5b} Helper to compute converted CAD amount from receipt's stored rate
		const getConvertedCAD = (receipt: ReceiptRow | null): number | null => {
			if (!receipt || !receipt.total_amount) return null;
			if (!receipt.currency || receipt.currency === 'CAD') return null;
			if (!receipt.exchange_rate_to_cad) return null;
			return receipt.total_amount * receipt.exchange_rate_to_cad;
		};

		// Add matched pairs (green rows at top)
		for (const pair of result.matched) {
			rows.push({
				id: `matched-${pair.receipt.id}-${pair.transaction.id}`,
				type: 'matched',
				receipt: pair.receipt,
				transaction: pair.transaction,
				date: pair.receipt.transaction_date,
				vendor: pair.receipt.merchant_name || pair.transaction.vendor_name,
				amount: pair.receipt.total_amount,
				creditCard: pair.transaction.credit_card_type,
				matchConfidence: pair.matchConfidence,
				convertedAmountCAD: getConvertedCAD(pair.receipt)
			});
		}

		// Add unmatched receipts
		for (const unmatched of result.unmatchedReceipts) {
			rows.push({
				id: `receipt-${unmatched.receipt.id}`,
				type: 'unmatchedReceipt',
				receipt: unmatched.receipt,
				transaction: null,
				date: unmatched.receipt.transaction_date,
				vendor: unmatched.receipt.merchant_name,
				amount: unmatched.receipt.total_amount,
				creditCard: unmatched.receipt.credit_card_name,
				convertedAmountCAD: getConvertedCAD(unmatched.receipt)
			});
		}

		// Add unmatched transactions
		for (const unmatched of result.unmatchedTransactions) {
			rows.push({
				id: `transaction-${unmatched.transaction.id}`,
				type: 'unmatchedTransaction',
				receipt: null,
				transaction: unmatched.transaction,
				date: unmatched.transaction.transaction_date,
				vendor: unmatched.transaction.vendor_name,
				amount: unmatched.transaction.amount,
				creditCard: unmatched.transaction.credit_card_type,
				convertedAmountCAD: null
			});
		}

		// Apply sorting if specified
		if (sort) {
			return this.sortDisplayRows(rows, sort);
		}

		return rows;
	}

	/**
	 * Sorts display rows by the specified field and direction
	 */
	private sortDisplayRows(
		rows: ReconciliationDisplayRow[],
		sort: ReconciliationSort
	): ReconciliationDisplayRow[] {
		const sortedRows = [...rows];
		const direction = sort.direction === 'asc' ? 1 : -1;

		sortedRows.sort((a, b) => {
			let aVal: string | number;
			let bVal: string | number;

			switch (sort.field) {
				case 'date':
					aVal = a.date || '';
					bVal = b.date || '';
					break;
				case 'vendor':
					aVal = a.vendor || '';
					bVal = b.vendor || '';
					break;
				case 'amount':
					aVal = a.amount || 0;
					bVal = b.amount || 0;
					break;
				case 'creditCard':
					aVal = a.creditCard || '';
					bVal = b.creditCard || '';
					break;
				case 'matchStatus': {
					const statusOrder = { matched: 0, unmatchedReceipt: 1, unmatchedTransaction: 2 };
					aVal = statusOrder[a.type];
					bVal = statusOrder[b.type];
					break;
				}
				default:
					return 0;
			}

			if (typeof aVal === 'string') {
				return direction * aVal.localeCompare(bVal as string);
			} else {
				return direction * (aVal - (bVal as number));
			}
		});

		return sortedRows;
	}
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ReconciliationService } from './ReconciliationService';
