				matched_transaction_id: 'txn-1', // ← Manually matched
				created_at: '2025-11-20T10:00:00Z'
			});

			// 2. The transaction that the receipt is matched to
			const matchedTransaction = makeTransactionRow({
				id: 'txn-1',
				family_id: familyId,
				vendor_name: 'Coffee Shop',
				amount: -5.99,
				transaction_date: '2025-11-20',
				credit_card_type: 'Visa',
				created_at: '2025-11-20T10:00:00Z',
				updated_at: '2025-11-20T10:00:00Z'
			});

			// 3. An unrelated unmatched transaction
			const unmatchedTransaction = makeTransactionRow({
				id: 'txn-2',
				family_id: familyId,
				vendor_name: 'Gas Station',
				amount: -45.0,
				transaction_date: '2025-11-21',
				credit_card_type: 'Mastercard',
				created_at: '2025-11-21T10:00:00Z',
				updated_at: '2025-11-21T10:00:00Z'
			});

			// Mock Supabase responses
			const mockReceiptsNot2 = vi.fn().mockResolvedValue({
				data: [manuallyMatchedReceipt],
				error: null
			});

			const mockReceiptsNot1 = vi.fn().mockReturnValue({
				not: mockReceiptsNot2
			});

			const mockReceiptsLte = vi.fn().mockReturnValue({
				not: mockReceiptsNot1
			});

			const mockReceiptsGte = vi.fn().mockReturnValue({
				lte: mockReceiptsLte
			});

			const mockReceiptsEq = vi.fn().mockReturnValue({
				gte: mockReceiptsGte
			});

			const mockReceiptsSelect = vi.fn().mockReturnValue({
				eq: mockReceiptsEq
			});

			const mockTransactionsLte = vi.fn().mockResolvedValue({
				data: [matchedTransaction, unmatchedTransaction],
				error: null
			});

			const mockTransactionsGte = vi.fn().mockReturnValue({
				lte: mockTransactionsLte
			});

			const mockTransactionsEq = vi.fn().mockReturnValue({
				gte: mockTransactionsGte
			});

			const mockTransactionsSelect = vi.fn().mockReturnValue({
				eq: mockTransactionsEq
			});

			vi.mocked(supabase.from).mockImplementation((table: string) => {
				const builder =
					table === 'receipts' ? { select: mockReceiptsSelect } : { select: mockTransactionsSelect };
				return builder as unknown as SupabaseQueryBuilder;
			});

			// Run reconciliation with includeManuallMatched: true
			const result = await service.reconcile(familyId, {
				startDate: '2025-11-01',
				endDate: '2025-11-30',
				includeManuallMatched: true
			});

			// ASSERTIONS:
			// 1. The manually matched receipt should appear in the matched pairs
			expect(result.matched).toHaveLength(1);
			expect(result.matched[0].receipt.id).toBe('receipt-1');
			expect(result.matched[0].transaction.id).toBe('txn-1');
			expect(result.matched[0].matchConfidence).toBe('high');

			// 2. The matched transaction (txn-1) should NOT appear in unmatchedTransactions
			// This is the key assertion that will fail before the fix
			const unmatchedTransactionIds = result.unmatchedTransactions.map((ut) => ut.transaction.id);
			expect(unmatchedTransactionIds).not.toContain('txn-1');

			// 3. Only the truly unmatched transaction (txn-2) should be in unmatchedTransactions
			expect(result.unmatchedTransactions).toHaveLength(1);
			expect(result.unmatchedTransactions[0].transaction.id).toBe('txn-2');

			// 4. Stats should be correct
			expect(result.stats.totalReceipts).toBe(1);
			expect(result.stats.totalTransactions).toBe(2);
			expect(result.stats.matchedCount).toBe(1);
			expect(result.stats.unmatchedTransactionCount).toBe(1); // Only txn-2, not txn-1
		});

		it('should correctly handle multiple manually matched receipts', async () => {
			const familyId = 'test-family-id';

			// Two manually matched receipts
			const receipt1 = makeReceiptRow({
				id: 'receipt-1',
				user_id: 'test-user-id',
				merchant_name: 'Coffee Shop',
				total_amount: 5.99,
				transaction_date: '2025-11-20',
				tax: null,
				currency: 'USD',
				receipt_image_path: null,
				matched_transaction_id: 'txn-1',
				created_at: '2025-11-20T10:00:00Z'
			});

			const receipt2 = makeReceiptRow({
				id: 'receipt-2',
				user_id: 'test-user-id',
				merchant_name: 'Restaurant',
				total_amount: 25.5,
				transaction_date: '2025-11-21',
				tax: null,
				currency: 'USD',
				receipt_image_path: null,
				matched_transaction_id: 'txn-2',
				created_at: '2025-11-21T10:00:00Z'
			});

			const txn1 = makeTransactionRow({
				id: 'txn-1',
				family_id: familyId,
				vendor_name: 'Coffee Shop',
				amount: -5.99,
				transaction_date: '2025-11-20',
				credit_card_type: 'Visa',
				created_at: '2025-11-20T10:00:00Z',
				updated_at: '2025-11-20T10:00:00Z'
			});

			const txn2 = makeTransactionRow({
				id: 'txn-2',
				family_id: familyId,
				vendor_name: 'Restaurant',
				amount: -25.5,
				transaction_date: '2025-11-21',
				credit_card_type: 'Visa',
				created_at: '2025-11-21T10:00:00Z',
				updated_at: '2025-11-21T10:00:00Z'
			});

			// Mock Supabase
			const mockReceiptsNot2 = vi.fn().mockResolvedValue({
				data: [receipt1, receipt2],
				error: null
			});

			const mockReceiptsNot1 = vi.fn().mockReturnValue({
				not: mockReceiptsNot2
			});

			const mockReceiptsLte = vi.fn().mockReturnValue({
				not: mockReceiptsNot1
			});

			const mockReceiptsGte = vi.fn().mockReturnValue({
				lte: mockReceiptsLte
			});

			const mockReceiptsEq = vi.fn().mockReturnValue({
				gte: mockReceiptsGte
			});

			const mockReceiptsSelect = vi.fn().mockReturnValue({
				eq: mockReceiptsEq
			});

			const mockTransactionsLte = vi.fn().mockResolvedValue({
				data: [txn1, txn2],
				error: null
			});

			const mockTransactionsGte = vi.fn().mockReturnValue({
				lte: mockTransactionsLte
			});

			const mockTransactionsEq = vi.fn().mockReturnValue({
				gte: mockTransactionsGte
			});

			const mockTransactionsSelect = vi.fn().mockReturnValue({
				eq: mockTransactionsEq
			});

			vi.mocked(supabase.from).mockImplementation((table: string) => {
				const builder =
					table === 'receipts' ? { select: mockReceiptsSelect } : { select: mockTransactionsSelect };
				return builder as unknown as SupabaseQueryBuilder;
			});

			const result = await service.reconcile(familyId, {
				startDate: '2025-11-01',
				endDate: '2025-11-30',
				includeManuallMatched: true
			});

			// Both receipts should be matched
			expect(result.matched).toHaveLength(2);

			// Neither transaction should appear in unmatchedTransactions
			expect(result.unmatchedTransactions).toHaveLength(0);

			// Stats should be correct
			expect(result.stats.matchedCount).toBe(2);
			expect(result.stats.unmatchedTransactionCount).toBe(0);
		});
	});

	describe('manualMatch', () => {
		it('should update receipt with transaction ID', async () => {
			const receiptId = 'receipt-1';
			const transactionId = 'txn-1';

			const updatedReceipt = makeReceiptRow({
				id: receiptId,
				user_id: 'user-1',
				merchant_name: 'Test Store',
				total_amount: 10.99,
				transaction_date: '2025-11-20',
				tax: null,
				currency: 'USD',
				receipt_image_path: null,
				matched_transaction_id: transactionId,
				created_at: '2025-11-20T10:00:00Z'
			});

			const mockSingle = vi.fn().mockResolvedValue({
				data: updatedReceipt,
				error: null
			});

			const mockSelect = vi.fn().mockReturnValue({
				single: mockSingle
			});

			const mockEq = vi.fn().mockReturnValue({
				select: mockSelect
			});

			const mockUpdate = vi.fn().mockReturnValue({
				eq: mockEq
			});

			vi.mocked(supabase.from).mockReturnValue({
				update: mockUpdate
			} as unknown as SupabaseQueryBuilder);

			const result = await service.manualMatch({
				receiptId,
				transactionId
			});

			expect(result.id).toBe(receiptId);
			expect(result.matched_transaction_id).toBe(transactionId);
			expect(mockUpdate).toHaveBeenCalledWith({ matched_transaction_id: transactionId });
			expect(mockEq).toHaveBeenCalledWith('id', receiptId);
		});
	});

	describe('manualUnmatch', () => {
		it('should clear receipt transaction ID', async () => {
			const receiptId = 'receipt-1';

			const unmatchedReceipt = makeReceiptRow({
				id: receiptId,
				user_id: 'user-1',
				merchant_name: 'Test Store',
				total_amount: 10.99,
				transaction_date: '2025-11-20',
				tax: null,
				currency: 'USD',
				receipt_image_path: null,
				matched_transaction_id: null,
				created_at: '2025-11-20T10:00:00Z'
			});

			const mockSingle = vi.fn().mockResolvedValue({
				data: unmatchedReceipt,
				error: null
			});

			const mockSelect = vi.fn().mockReturnValue({
				single: mockSingle
			});

			const mockEq = vi.fn().mockReturnValue({
				select: mockSelect
			});

			const mockUpdate = vi.fn().mockReturnValue({
				eq: mockEq
			});

			vi.mocked(supabase.from).mockReturnValue({
				update: mockUpdate
			} as unknown as SupabaseQueryBuilder);

			const result = await service.manualUnmatch(receiptId);

			expect(result.id).toBe(receiptId);
			expect(result.matched_transaction_id).toBeNull();
			expect(mockUpdate).toHaveBeenCalledWith({ matched_transaction_id: null });
			expect(mockEq).toHaveBeenCalledWith('id', receiptId);
		});
	});
});

